    htalent_595_description: "Fox Trick Talent restores hero's <num>%s</num> Health (from the greatest of Strength and Intellect).",
    htalent_596_name: 'Buran',
    htalent_596_description:
      'The Blizzard talent additionally deals <mag>%s</mag> damage once every <num>3</num> seconds and lasts <num>1</num> second longer.',
    htalent_597_name: 'Chills',
    htalent_597_description:
      'Talent The impregnability of cold additionally reduces the damage inflicted on the hero from attacks and talents by <num>25%</num>.',
    htalent_598_name: 'Shower of arrows',
    htalent_598_description:
      'The time to create the Striking Barrage talent is reduced to <num>0.2</num> seconds, and damage is increased by <num>15%</num>. If a talent hits an enemy hero, his cooldown is reduced by <num>3</num> seconds. <br>Total damage <num>%s</num><fiz></fiz> and <mag></mag>. <br><rz>Total damage <num>%s</num><fiz></fiz> and <mag></mag>.</rz>',
    htalent_599_name: 'One step ahead',
    htalent_599_description:
      'The talent range of the new position increases by <num>30%</num>, and the amount of damage absorbed by the shield by <num>20%</num>.',
    htalent_600_name: 'Impenetrable',
    htalent_600_description: 'The Stony Talent additionally reduces the damage inflicted on the hero by <num>15%</num>.',
    htalent_601_name: 'Deafening Roar',
    htalent_601_description:
      'The Shockwave talent stuns enemies after being thrown for <num>0.4</num> seconds, disarms all affected enemy heroes for <num>1.5</num> seconds, gets the opportunity to pass through creatures for <num>3</num> seconds, inflicts <fiz>%s</fiz> damage (from Maximum health) to enemies below him every <num>0.5</num> seconds while the hero is moving.',
    htalent_602_name: 'Explosive charge',
    htalent_602_description:
      "The hero's attacks during the action of the Red-hot Barrel talent accumulate charges on the enemy. When the third charge accumulates, the enemy takes <mag>%s</mag> damage (from the highest of Strength and Intellect), but the charges are reset.",
    htalent_603_name: 'Security mark',
    htalent_603_description:
      "Extends the duration of the Hunter's Mark talent by <num>2</num> seconds. Damage received from an enemy with a Hunter's Mark is additionally reduced by <num>5%</num>, and from other sources by <num>15%</num>. <br>The target\'s speed additionally reduced by <num>20%</num>. When the mark expires, it deals an additional <mag>%s</mag> damage (from Intellect).",
    htalent_604_name: 'Fire',
    htalent_604_description: 'A fiery blow leaves behind a burning earth, dealing <mag>%s</mag> damage for <num>3</num> seconds.',
